INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_d4fe716d2f0346709058507ce5d93357', 'content-rules-platform-v4', 'FRM01', '价格营销型', 'core', '["decoration"]', '以真实价格或报价口径吸引注意，再解释费用构成、服务边界和工长价值。', '["施工报价", "半包报价", "毛坯房装修"]', '["{location}{business}，这份{quote_type}先把钱花在哪讲清楚"]', '{"business_mode": "A", "evidence": ["真实报价", "报价口径"]}', '["location", "product", "price"]', '["价格必须来自用户确认或已核验资料", "必须说明报价类型和包含范围", "不得把预算写成成交或结算价"]', true, 5);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_4dc3bb572ffa47d3b5c7cbc48800b7fd', 'content-rules-platform-v4', 'FRM02', '案例故事型', 'core', '["decoration"]', '从真实业主问题和需求出发，用解决过程、施工证据与结果建立信任。', '["旧房改造", "老破小", "局部翻新", "典型案例", "日常工作"]', '["这次{location}{house}，先解决的是{needs}"]', '{"business_mode": "B", "evidence": ["案例背景", "施工过程", "结果"]}', '["location", "product", "pain", "process", "result"]', '["不得虚构业主、需求、对话、过程或反馈", "计划中的结果不得写成已经完成"]', true, 6);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_9e84934cb78544749c7e834cae9d0879', 'content-rules-platform-v4', 'FRM03', '用户痛点型', 'core', '["decoration"]', '先回应装修业主当下最担心的问题，再用真实案例、方案和报价降低决策风险。', '["担心增项", "怕乱拆乱改", "联系不到工长", "预算有限"]', '["如果你最担心{pain}，先看方案和报价是不是对得上"]', '{"business_mode": "C", "evidence": ["痛点", "解决方案", "真实报价"]}', '["pain", "product", "price", "advantages"]', '["不得制造虚假恐慌", "痛点必须与当前业务场景一致"]', true, 7);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_045650e0b26a4f2da84bc99cac7def63', 'content-rules-platform-v4', 'FRM04', '工艺专业型', 'core', '["decoration"]', '围绕一个具体施工问题，给出可核验的标准、现场证据与验收方法。', '["卫生间", "防水", "水电", "贴砖", "油漆"]', '["{project}做得对不对，现场主要看{process}"]', '{"business_mode": "D", "evidence": ["施工标准", "现场实拍", "验收方式"]}', '["product", "process"]', '["施工标准必须来自核验资料", "图片只能证明画面中可见的空间、阶段和工种"]', true, 8);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_9f9f1b371c734d03aa225af1c9f35543', 'content-rules-platform-v4', 'FRM05', '工长自荐型', 'core', '["decoration"]', '用真实身份、做事方式和可核验证据介绍工长，每篇只选择与当前用户顾虑相关的二至三项优势。', '["自我介绍", "本地获客", "服务边界", "日常工作"]', '["我是{location}做{business}的{identity}"]', '{"business_mode": "E", "persona_layers": ["身份", "价值", "证据"]}', '["location", "persona_fact", "advantages"]', '["身份、经验和案例必须真实", "单篇最多使用三项相关优势", "不得自造质保、响应时效或服务承诺"]', true, 9);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_fdcad56c3f9d49c3b0a42070a7bd0bc9', 'content-rules-platform-v4', 'FRM06', '项目单价型', 'core', '["decoration"]', '按具体施工项目展示真实单价、适用条件和包含范围，帮助业主判断报价。', '["人工工价行情", "单项人工价格"]', '["{location}{project}怎么收费，先看单价和包含范围"]', '{"business_mode": "F", "price_basis": ["standard_unit_price", "project_quote"]}', '["location", "product", "price"]', '["标准单价必须明确标注为参考", "标准单价不得冒充本案成交或结算价格", "不得倒推工程量或小计"]', true, 10);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_fabc1ee5fc8240e6b5020526a338410a', 'content-rules-platform-v4', 'FRM07', '单价+面积型', 'core', '["decoration"]', '在面积与单价均为同一真实口径时展示计算过程、重点项目和总价。', '["卫生间", "厨房", "局部翻新", "按面积计价"]', '["{location}{area}{business}，按{price}计算"]', '{"business_mode": "G", "calculation": "deterministic"}', '["location", "quantity", "product", "price"]', '["面积、单价和总价必须是同一项目口径", "计算不一致时阻断发布", "标准单价不可直接乘以项目面积推导成交总价"]', true, 11);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_2e079f851c6049b9af9db60ec31ea050', 'content-rules-platform-v4', 'FRM08', '工种总价型', 'core', '["decoration"]', '以真实总价为钩子，按工种说明包含项和预算分配。', '["半包", "硬装", "全屋基础施工"]', '["{location}{area}{business}，各工种总价这样分"]', '{"business_mode": "H", "evidence": ["工种总价", "包含项"]}', '["location", "quantity", "product", "price"]', '["各工种总价必须来自同一真实报价", "合计不一致时阻断发布", "不得补造未提供的分项"]', true, 12);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_fb77b3471cf445018b449b717416a3c8', 'content-rules-platform-v4', 'FRM09', '人工+辅材型', 'core', '["decoration"]', '把人工与辅材拆开说明，再按工种解释花费原因和透明服务价值。', '["半包", "硬装", "真实账单"]', '["这份{business}总价里，人工和辅材分别花在哪"]', '{"business_mode": "I", "evidence": ["人工合计", "辅材合计", "工种拆分"]}', '["product", "price", "process"]', '["人工、辅材和总价必须来自同一真实报价", "合计不一致时阻断发布", "透明优势必须有服务证据"]', true, 13);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_e63065a846044a89a9aba01ad6548f64', 'content-rules-platform-v5', 'M01', '数字法', 'core', '["food", "education", "beauty", "retail", "professional-services"]', '用可验证的数字降低决策成本，强化真实、透明和专业度。', '["价格拆解", "案例复盘", "周期说明", "效果对比"]', '["只用{number}，完成{result}", "{number}个关键点，讲清{topic}"]', '{"core": ["透明", "真实", "量化"]}', '["number", "result"]', '["数字必须有来源", "不得虚构效果或统计结论"]', true, 0);
