INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_8e259a4d7f40497091c4e528f56f36c4', 'content-rules-platform-v5', 'M03', '价值法', 'core', '["food", "education", "beauty", "retail", "professional-services"]', '直接表达用户可获得的利益、资源或解决方案。', '["清单", "攻略", "解决方案", "服务介绍"]', '["帮你{result}的{number}个方法", "看完就能{action}"]', '{"core": ["价值", "攻略", "解决方案"]}', '["result", "advantages"]', '["收益不得超出证据支持范围"]', true, 2);
